  ('contact', '{"company":"SIA \"JUALEKS\"","address":"Pasta iela 25","city":"Tukums","postalCode":"LV-3101","email":"smaidu.darbnica@gmail.com","emailPrivate":"smaidu.darbniica@gmail.com","phoneBusiness":"+371 26 705 817","phoneBusinessPerson":"Kristīne","phonePrivate":"+371 28 193 386","phonePrivatePerson":"Vanesa","hours":"Katru dienu 9.00–16.00","heroImage":"/media/smaidu-darbnica/smaidu-darbnica-01.webp","mapQuery":"Pasta iela 25, Tukums, LV-3101","facebook":"https://www.facebook.com/smaidudarbnica","instagram":"https://www.instagram.com/smaidu_darbnica/","tiktok":"https://www.tiktok.com/@smaidudarbnica","legalName":"Sabiedrība ar ierobežotu atbildību \"JUALEKS\"","legalAddress":"Zemgales iela 8, Tukums, LV-3101","regNr":"40002054493","vatNr":"LV40002054493","bank":"","iban":""}'::jsonb),
  ('home', '{"heroEyebrow":"Pasākumu aģentūra uzņēmumiem un pašvaldībām","heroTitle":"Mūsu misija — radīt","heroHighlight":"smaidu","heroAfter":"","heroText":"Mēs parūpēsimies par Jūsu pasākumu organizēšanu no A līdz Ž! No idejas līdz pēdējam akcentam – mūsu komanda nodrošinās scenārija izstrādi, dekorācijas, tehnisko nodrošinājumu un visas citas nianses, lai Jūs varētu baudīt pasākumu bez raizēm.","heroTextMobile":"Mēs parūpēsimies par Jūsu pasākumu organizēšanu no A līdz Ž — no idejas līdz pēdējam akcentam, lai Jūs varētu baudīt pasākumu bez raizēm.","heroPhotos":[{"src":"/media/vizium-jubileja/vizium-jubileja-09.webp","caption":"Burbuļu šovs"},{"src":"/media/ziemassvetki-2025/ziemassvetki-2025-23.webp","caption":"Ziemassvētki"},{"src":"/media/lielformata-speles/lielformata-speles-06.webp","caption":"Lielformāta spēles"}],"heroVideo":"","heroPoster":"/media/smaidu-darbnica/smaidu-darbnica-09.webp","heroCtaPrimary":"Pieprasīt piedāvājumu","heroCtaSecondary":"Apskatīt pakalpojumus","stats":[{"value":"10+","label":"gadu pieredze"},{"value":"45+","label":"tematiski tēli"},{"value":"1","label":"kontaktpersona visam pasākumam"},{"value":"Visa Latvija","label":"izbraucam pie jums"}],"servicesTitle":"Viss vienam veiksmīgam pasākumam","servicesText":"Izvēlieties atsevišķu aktivitāti vai uzticiet mums visu pasākumu — scenāriju, vadītājus, atrakcijas, dekorācijas un bērnu zonu.","whyTitle":"Kāpēc uzņēmumi izvēlas mūs","whyText":"Mēs zinām, ka pasākuma organizēšana ir papildu darbs jūsu ikdienā. Tāpēc uzņemamies atbildību no pirmā zvana līdz pēdējam viesim.","why":[{"title":"Viens kontakts visam","description":"Personīgs projekta vadītājs, kas koordinē programmu, laikus un komandu. Jums nav jāorganizē desmit piegādātāji."},{"title":"10 gadu pieredze","description":"Esam strādājuši uzņēmumu jubilejās, pilsētu svētkos un festivālos ar simtiem un tūkstošiem dalībnieku."},{"title":"Programma pēc jūsu mērķa","description":"Pielāgojam saturu dalībnieku vecumam, skaitam, telpai un pasākuma formātam — iekštelpās vai ārā."},{"title":"Droši un profesionāli","description":"Pārbaudīts inventārs, pieredzējuši animatori un skaidri līgumi ar rēķinu uzņēmumam."}],"processTitle":"Kā mēs strādājam","process":[{"title":"Pieteikums","description":"Pastāstiet par pasākumu — datums, vieta, dalībnieku skaits un mērķis."},{"title":"Piedāvājums","description":"Vienas darba dienas laikā sagatavojam programmu un izmaksu tāmi."},{"title":"Sagatavošana","description":"Saskaņojam scenāriju, laikus un tehniskās detaļas ar jūsu komandu."},{"title":"Pasākums","description":"Ierodamies laikus, vadām programmu un sakārtojam vietu pēc sevis."}],"galleryTitle":"No mūsu pasākumiem","galleryText":"Ieskats pasākumos, ko esam veidojuši uzņēmumiem, pašvaldībām un festivāliem.","galleryImages":["/media/tukuma-rozu-svetki-2025/tukuma-rozu-svetki-2025-08.webp","/media/ziemassvetki-2025/ziemassvetki-2025-03.webp","/media/lielformata-speles/lielformata-speles-01.webp","/media/valpurgu-nakts-tervete-2026/valpurgu-nakts-tervete-2026-10.webp","/media/dobeles-pilsetas-svetki-2026/dobeles-pilsetas-svetki-2026-05.webp","/media/stiga-meza-dienas/stiga-meza-dienas-02.webp","/media/tukuma-rozu-svetki-2025/tukuma-rozu-svetki-2025-07.webp","/media/vizium-jubileja/vizium-jubileja-07.webp","/media/ziemassvetki-2025/ziemassvetki-2025-17.webp","/media/mazulu-sturitis/mazulu-sturitis-01.webp","/media/valpurgu-nakts-tervete-2026/valpurgu-nakts-tervete-2026-13.webp","/media/lielformata-speles/lielformata-speles-09.webp"],"xmasEnabled":true,"xmasEyebrow":"Ziemassvētki 2026","xmasTitle":"Svētku sezona","xmasHighlight":"tuvojas","xmasText":"Svētku programmas uzņēmumiem, pašvaldībām un skolām. Decembra nedēļas nogales aizpildās visātrāk — rezervējiet laicīgi.","xmasShort":"Izrādes, rūķi un Ziemassvētku vecītis jūsu uzņēmuma vai pilsētas svētkiem. Decembris aizpildās ātri — rezervējiet laicīgi.","xmasPoints":[],"xmasPhotos":[{"src":"/media/ziemassvetki-2025/ziemassvetki-2025-03.webp","caption":"Ziemassvētku izrāde"},{"src":"/media/ziemassvetki-2025/ziemassvetki-2025-28.webp","caption":"Rūķi"},{"src":"/media/ziemassvetki-2025/ziemassvetki-2025-17.webp","caption":"Radošās darbnīcas"}],"ctaTitle":"Plānojat pasākumu?","ctaText":"Pastāstiet mums par savu ideju — sagatavosim piedāvājumu vienas darba dienas laikā.","xmasCards":[{"title":"Izrādes","text":"Ziemassvētku izrādes visai ģimenei — “Ziemassvētku faktors”, “Dāvanu prieks” un “Dāvanu recepte”. Noskatieties video.","image":"/media/ziemassvetki-2025/ziemassvetki-2025-09.webp"},{"title":"Radošās darbnīcas","text":"Radošās darbnīcas bērniem un pieaugušajiem — dalībnieki paši izgatavo suvenīru, ko paņemt līdzi.","image":"/media/ziemassvetki-2025/ziemassvetki-2025-18.webp"},{"title":"Pasākumu vadīšana un organizēšana","text":"Pasākuma organizēšana un vadīšana no idejas līdz noslēgumam — scenārijs, vadītājs, programma un viss nepieciešamais. Jums ir viens kontakts, kas koordinē visu pasākumu.","image":"/media/ziemassvetki-2025/pasakumu-vadisana.webp"},{"title":"Egles iedegšana","text":"Pilsētu un pašvaldību egles iedegšanas svētki ar programmu visai ģimenei.","image":"/media/ziemassvetki-2025/egles-iedegsana.webp"}],"doors":[{"tag":"Uzņēmumiem","title":"Visu veidu pasākumi","text":"Uzņēmumu, pilsētu un skolu svētki, Ziemassvētku un vasaras pasākumi, radošās darbnīcas un lielformāta spēles.","image":"/media/smaidu-darbnica/uznemumiem-kartite-v2.webp","href":"/uznemumiem"},{"tag":"Izrādes","title":"Izrādes visai ģimenei","text":"Interaktīvas izrādes uz skatuves — Ziemassvētku un vasaras uzvedumi.","image":"/media/izrades/izrade-09.webp","href":"/izrades"},{"tag":"Privātpersonām","title":"Bērnu ballītes","text":"Tematiskas bērnu ballītes ar animatoriem mūsu telpās vai pie jums.","image":"/media/tukuma-rozu-svetki-2025/tukuma-rozu-svetki-2025-08.webp","href":"/izklaides-programmas"},{"tag":"Tukums","title":"Telpu noma","text":"Bumbu baseins, disko zāle un virtuve Tukuma centrā.","image":"/media/telpas/telpas-03.webp","href":"/telpu-noma"}]}'::jsonb),
  ('about', '{"title":"Radām smaidus jau vairāk nekā 10 gadus","intro":"Smaidu Darbnīca ir pasākumu aģentūra Tukumā, kas organizē izklaides programmas uzņēmumiem, pašvaldībām, skolām un ģimenēm visā Latvijā.","image":"/media/par-mums/par-mums-02.webp","story":"Mēs sākām ar bērnu ballītēm, un šodien mūsu komanda veido pilsētu svētkus, uzņēmumu jubilejas, Ziemassvētku pasākumus un festivālu bērnu zonas ar tūkstošiem apmeklētāju.\n\nNo idejas līdz pēdējam akcentam — izstrādājam scenāriju, sagatavojam dekorācijas, aktivitātes un muzikālos priekšnesumus. Programmu vienmēr pielāgojam dalībnieku vecumam, skaitam un pasākuma formātam.\n\nMūsu mērķis ir vienkāršs: lai jūs varat mierīgi baudīt svētkus, bet viesi aiziet mājās ar siltām atmiņām.","values":[{"title":"Uzticamība","description":"Ierodamies laikā, turam solīto un vienmēr esam sazvanāmi."},{"title":"Radošums","description":"Katram pasākumam — sava ideja, tēli un detaļas."},{"title":"Drošība","description":"Pārbaudīts inventārs un pieredzējusi komanda, kas pieskata katru dalībnieku."},{"title":"Prieks","description":"Smaids ir mūsu darba rezultāts — gan bērniem, gan pieaugušajiem."}],"teamTitle":"Komanda","teamText":"Pieredzējuši pasākumu vadītāji, animatori un radošie cilvēki, kas savu darbu dara ar sirdi."}'::jsonb),
  ('business', '{"heroTitle":"Pasākumi, kas","heroHighlight":"saliedē","heroText":"Lielformāta spēles, radošās darbnīcas, mazuļu zona, sejas apgleznošana, putu ballīte, sporta spēles un izrādes — kā arī pasākuma vadīšana un organizēšana.","winterText":"Ziemassvētku izrādes, rūķu programmas, Ziemassvētku vecītis un radošās darbnīcas darbinieku bērniem, klientiem un pilsētu svētkiem.","summerText":"Vasaras ballītes, ģimenes dienas un pilsētu svētki brīvā dabā — radošās darbnīcas, lielformāta spēles, burbuļu šovi un seju apgleznošana.","allYearText":"Komandas saliedēšana, uzņēmumu jubilejas un bērnu zonas jebkurā gadalaikā.","showsTitle":"Izrādes jūsu pasākumam","showsText":"Interaktīvas izrādes ar mūsu tēliem uz skatuves — Ziemassvētku un vasaras uzvedumi. Video un vairāk informācijas sadaļā “Izrādes”.","photosTitle":"No mūsu pasākumiem","heroImage":"/media/hero/pasakums-06.webp","games":[{"name":"Garās kājas","image":"/media/speles/garas-kajas.jpg"},{"name":"Jenga","image":"/media/speles/jenga.webp"},{"name":"Katapulta","image":"/media/speles/katapulta.webp"},{"name":"Līdzsvara dēlis","image":"/media/speles/lidzsvarudelis.webp"},{"name":"Limbo","image":"/media/speles/limbo.webp"},{"name":"Melnais caurums","image":"/media/speles/melnaiscaurums.webp"},{"name":"Slēpes","image":"/media/speles/slepes.webp"},{"name":"Smaidiņu cope","image":"/media/speles/smaidinucope.webp"},{"name":"Veiksmīgais loms","image":"/media/speles/veiksmigaisloms.webp"},{"name":"Pīļuks pa dambi","image":"/media/speles/pilukspadambi.webp"},{"name":"Desas","image":"/media/speles/desas.webp"},{"name":"Tornis","image":"/media/speles/tornis.webp"},{"name":"Saldumu zeme","image":"/media/speles/saldumuzeme.webp"},{"name":"Peļu slazds","image":"/media/speles/peuslazds.webp"},{"name":"Slinkais šoferītis","image":"/media/speles/slinkaissoferitis.webp"},{"name":"Lielformāta smaidiņš","image":"/media/speles/lielformatasmaidins.webp"},{"name":"Dambrete","image":"/media/speles/dambrete.webp"},{"name":"Acenes","image":"/media/speles/acenes.webp"},{"name":"Bišu šūniņas","image":"/media/speles/bisusuninas.webp"},{"name":"Bungas","image":"/media/speles/bungas.webp"}],"servicePhotos":{"pasakumu-organizesana":["/media/pasakumu-organizesana/pasakums-01.webp","/media/pasakumu-organizesana/pasakums-02.webp","/media/pasakumu-organizesana/pasakums-03.webp","/media/pasakumu-organizesana/pasakums-04.webp","/media/pasakumu-organizesana/pasakums-05.webp","/media/pasakumu-organizesana/pasakums-06.webp","/media/pasakumu-organizesana/pasakums-07.webp","/media/pasakumu-organizesana/pasakums-08.webp","/media/pasakumu-organizesana/pasakums-09.webp","/media/pasakumu-organizesana/pasakums-10.webp","/media/pasakumu-organizesana/pasakums-11.webp","/media/pasakumu-organizesana/pasakums-12.webp","/media/pasakumu-organizesana/pasakums-13.webp","/media/pasakumu-organizesana/pasakums-14.webp","/media/pasakumu-organizesana/pasakums-15.webp","/media/pasakumu-organizesana/pasakums-16.webp","/media/pasakumu-organizesana/pasakums-17.webp","/media/pasakumu-organizesana/pasakums-18.webp","/media/pasakumu-organizesana/pasakums-19.webp","/media/pasakumu-organizesana/pasakums-20.webp","/media/pasakumu-organizesana/pasakums-21.webp","/media/pasakumu-organizesana/pasakums-22.webp"],"sporta-speles":["/media/uznemumiem-sporta-speles/sporta-speles-01.webp","/media/uznemumiem-sporta-speles/sporta-speles-02.webp","/media/uznemumiem-sporta-speles/sporta-speles-03.webp","/media/uznemumiem-sporta-speles/sporta-speles-04.webp","/media/uznemumiem-sporta-speles/sporta-speles-05.webp","/media/uznemumiem-sporta-speles/sporta-speles-06.webp","/media/uznemumiem-sporta-speles/sporta-speles-07.webp","/media/uznemumiem-sporta-speles/sporta-speles-08.webp"],"radosas-darbnicas":["/media/uznemumiem-radosas-darbnicas/radosas-darbnicas-01.webp","/media/uznemumiem-radosas-darbnicas/radosas-darbnicas-02.webp","/media/uznemumiem-radosas-darbnicas/radosas-darbnicas-03.webp","/media/uznemumiem-radosas-darbnicas/radosas-darbnicas-04.webp","/