insert into public.team_members (name, role, bio, photo, sort, published)
select * from (values
  ('Kristīne', 'Dibinātāja un pasākumu vadītāja', 'Smaidu Darbnīcas sirds un dzinējspēks. Kristīne atrod risinājumu jebkurā situācijā, iedvesmo komandu un rūpējas, lai katrs pasākums noritētu nevainojami.', '/media/komanda/kristine.webp', 10, true),
  ('Madara', 'Radošā projektu vadītāja', 'Ideju ģenerators un kvalitātes perfekcioniste. Atbild par pasākumu koncepcijām, dekorācijām un to, lai katra detaļa būtu savā vietā.', '/media/komanda/madara-radosa.webp', 20, true),
  ('Gunta', 'Vecākā animatore', 'Vairāk nekā 10 gadu pieredze un desmitiem iemīļotu tēlu. Gunta zina, kā aizraut jebkuru auditoriju.', '/media/komanda/gunta.webp', 30, true),
  ('Agija', 'Animatore', 'Mūsu komandas dzirkstelīte, kas katru pasākumu piepilda ar siltumu, zināšanām un pozitīvu enerģiju.', '/media/komanda/agija.webp', 40, true),
  ('Madara', 'Animatore', 'Enerģiska animatore ar pedagoga pieredzi, kas aizrauj ar spēlēm, dejām un piedzīvojumiem.', '/media/komanda/madara-animatore.webp', 50, true),
  ('Vanesa', 'Administratore', 'Parūpējas, lai viss ritētu gludi — no rezervācijām līdz mājaslapas tehniskajai pusei.', '/media/komanda/vanesa.webp', 60, true),
  ('Keita', 'Klientu uzņemšana', 'Pirmais smaids, kas sagaida viesus. Keita rūpējas par sirsnīgu uzņemšanu un kārtību.', '/media/komanda/keita.webp', 70, true)
) as v(name, role, bio, photo, sort, published)
where not exists (select 1 from public.team_members);


